func listSkills(io *iostreams.IOStreams, skills []discovery.Skill) {
	isTTY := io.IsStdoutTTY()
	for _, s := range skills {
		if isTTY {
			if s.Description != "" {
				fmt.Fprintf(io.Out, "%s - %s\n", s.DisplayName(), s.Description)
			} else {
				fmt.Fprintf(io.Out, "%s\n", s.DisplayName())
			}
		} else {
			fmt.Fprintf(io.Out, "%s\t%s\n", s.DisplayName(), s.Description)
		}
	}
}

